const MODE_EMOJI = {
  food: { brunch:"🥐", coffee:"☕", boba:"🥤", matcha:"🍵", thai:"🌶", diner:"🍳", burgers:"🍔", steakhouse:"🥩", japanese:"🍣", korean:"🥩", chinese:"🥢", pasta:"🍝", french:"🥐", pizza:"🍕", mediterranean:"🥙", mexican:"🌮", peruvian:"🫙", colombian:"🫘", indian:"🍛", halal:"🌙", vegan:"🌿", american:"🥩", latenight:"🌙", default:"🍽️" },
  drinks: { cocktails:"🍸", beer:"🍺", wine:"🍷", experimental:"🧪", speakeasy:"🕯️", default:"🥂" },
  fooddrinks: { dinner_cocktails:"🍸", wine_plates:"🍷", brunch_drinks:"🥂", late_bites:"🌙", default:"🥂" },
  activity: { outside:"🌿", creative:"🎨", competitive:"🎯", shows:"🎭", active:"💪", default:"✨" },
  happyhour: { default:"🎉" },
};

const getModeEmoji = (focus, subtype) => {
  const map = MODE_EMOJI[focus];
  if (!map) return "✨";
  return map[subtype] || map.default;
};

const ResultCards = ({ spots, mode, dateType, onReset, neighborhood, answers }) => {
  const [idx, setIdx] = useState(0);
  const HOOD_LABELS = { williamsburg:"Williamsburg Brooklyn", east_village:"East Village New York", west_village:"West Village New York", midtown:"Midtown Manhattan", lic:"Long Island City Queens", bushwick:"Bushwick Brooklyn", fidi:"Financial District Manhattan", upper_east:"Upper East Side New York", upper_west:"Upper West Side New York" };
  const mapsUrl = (spot) => {
    const hoodLabel = HOOD_LABELS[neighborhood] || "New York NY";
    const query = encodeURIComponent(`${spot.place} ${hoodLabel}`);
    return `https://www.google.com/maps/search/?api=1&query=${query}`;
  };
  const resyUrl = (name) => `https://resy.com/cities/ny?query=${encodeURIComponent(name)}`;

  if (!spots || !spots.length) return (
    <div style={{textAlign:"center",color:T.sub,padding:"32px 16px",fontFamily:"sans-serif",display:"flex",flexDirection:"column",gap:"20px",alignItems:"center"}}>
      <div style={{fontSize:"48px",opacity:0.4}}>🔍</div>
      <div style={{fontSize:"14px",color:T.sub,lineHeight:1.5}}>No spots match that combo in this neighborhood.<br/>Try a different pick.</div>
      <button onClick={onReset}
        style={{background:"transparent",border:`1px solid ${T.accent}66`,color:T.accent,padding:"12px 28px",cursor:"pointer",fontFamily:"sans-serif",fontSize:"11px",letterSpacing:"3px",textTransform:"uppercase",fontWeight:"700",borderRadius:"4px",marginTop:"8px"}}>
        ↺ Start Over
      </button>
    </div>
  );

  const spot = spots[idx];
  const isGem = gemScore(spot.reviews) >= 8;
  const cycleNext = () => setIdx(i => (i + 1) % spots.length);
  const remaining = spots.length - idx - 1;
  const nbAccent = {williamsburg:"#c9a96e",east_village:"#9b6b9b",west_village:"#6b9b8b",midtown:"#ff8c42",lic:"#c9a96e",bushwick:"#e85d75",fidi:"#6b8bbd",upper_east:"#9b6b9b",upper_west:"#6b9b8b"}[neighborhood] || T.accent;
  const starRating = spot.stars || 0;
  const fullStars = Math.floor(starRating);
  const halfStar = starRating - fullStars >= 0.5;
  const SKIP_DESCS = ["brunch","bar","late night","latenight","dinner","activity","pizza","japanese","italian dinner","american dinner","mediterranean","cocktail bar","wine bar","speakeasy","rooftop","happy hour","coffee","matcha","korean","chinese","mexican","vegan","american","food"];
  const descRaw = spot.desc || "";
  const isRawType = SKIP_DESCS.includes(descRaw.toLowerCase().trim()) || 
    (descRaw.length > 0 && descRaw[0] >= '0' && descRaw[0] <= '9') ||
    descRaw === spot.type || descRaw === spot.subtype;
  const desc = descRaw && descRaw !== spot.place && !isRawType && descRaw.length > 10 ? descRaw : null;
  const subtype = answers?.drinkType || answers?.foodType || answers?.foodDrinkType || answers?.activityType || "";
  const catEmoji = getModeEmoji(mode, subtype);

  return (
    <div style={{display:"flex",flexDirection:"column",gap:"12px"}}>

      <div style={{background:"linear-gradient(160deg,#0e0a16,#080610)",border:`1px solid ${nbAccent}55`,borderRadius:"16px",overflow:"hidden",boxShadow:`0 32px 80px rgba(0,0,0,0.9),0 0 0 1px rgba(255,255,255,0.03),inset 0 1px 0 rgba(255,255,255,0.05)`}}>

        <div style={{height:"3px",background:`linear-gradient(90deg,transparent,${nbAccent},${nbAccent}88,transparent)`}}/>

        {spot.photo && spot.photo.length > 10 && !spot.photo.includes('_placeholder') && !spot.photo.startsWith('http') && (
          <div data-photo="1" style={{position:"relative",width:"100%",height:"180px",overflow:"hidden",background:"#0e0a16"}}>
            <img src={`/api/photo?ref=${encodeURIComponent(spot.photo)}`} alt=""
              style={{width:"100%",height:"100%",objectFit:"cover",display:"block",opacity:0,transition:"opacity 0.3s ease-in"}}
              onLoad={e=>{e.currentTarget.style.opacity="0.85";}}
              onError={e=>{const p=e.currentTarget.closest('[data-photo]');if(p)p.style.display="none";}}
            />
            <div style={{position:"absolute",inset:0,background:`linear-gradient(to bottom,transparent 40%,#0e0a16 100%)`,pointerEvents:"none"}}/>
            <div style={{position:"absolute",bottom:"6px",right:"8px",fontSize:"8px",color:"rgba(255,255,255,0.4)",fontFamily:"sans-serif"}}>📷 Google</div>
          </div>
        )}

        <div style={{padding:"18px 20px 0",display:"flex",justifyContent:"space-between",alignItems:"center",textAlign:"center"}}>
          <span style={{fontSize:"9px",letterSpacing:"3px",textTransform:"uppercase",color:nbAccent,fontFamily:"sans-serif",opacity:0.9}}>
            {idx === 0 ? "Tonight's Pick" : `Pick ${idx + 1} of ${spots.length}`}
          </span>
          {mode !== "activity" && <span style={{fontSize:"18px",lineHeight:1,opacity:0.6}}>{catEmoji}</span>}
        </div>

        <div style={{padding:"12px 20px 16px"}}>
          <h2 style={{fontSize:"clamp(28px,7vw,42px)",fontWeight:"300",lineHeight:1.05,margin:"0 0 8px",letterSpacing:"-0.5px",color:"#fff",fontFamily:"Georgia, serif",textAlign:"center"}}>{spot.place}</h2>
          <div style={{display:"flex",gap:"6px",flexWrap:"wrap"}}>
            {isGem && (
              <div style={{display:"inline-flex",alignItems:"center",gap:"4px",background:`${nbAccent}18`,border:`1px solid ${nbAccent}44`,borderRadius:"20px",padding:"3px 10px"}}>
                <span style={{fontSize:"9px"}}>💎</span>
                <span style={{fontSize:"9px",letterSpacing:"1.5px",textTransform:"uppercase",color:nbAccent,fontFamily:"sans-serif"}}>Hidden Gem</span>
              </div>
            )}
            {spot.featured && (
              <div style={{display:"inline-flex",alignItems:"center",gap:"4px",background:"linear-gradient(135deg,#c9a96e,#b8860b)",borderRadius:"20px",padding:"3px 10px"}}>
                <span style={{fontSize:"9px",letterSpacing:"1.5px",textTransform:"uppercase",color:"#000",fontFamily:"sans-serif",fontWeight:"700"}}>⭐ Featured</span>
              </div>
            )}
          </div>
        </div>

        <div style={{margin:"0 20px",height:"1px",background:`linear-gradient(90deg,${nbAccent}44,transparent)`}}/>

        <div style={{padding:"14px 20px",display:"flex",alignItems:"center",gap:"8px",flexWrap:"wrap"}}>
          <div style={{display:"flex",alignItems:"center",gap:"2px"}}>
            {Array.from({length:5}).map((_,i) => (
              <span key={i} style={{fontSize:"13px",color:i < fullStars ? "#f4c542" : (i === fullStars && halfStar ? "#f4c542" : "#333")}}>★</span>
            ))}
          </div>
          <span style={{fontSize:"15px",fontWeight:"600",color:"#fff",fontFamily:"sans-serif"}}>{starRating}</span>
          {spot.reviews > 0 && (
            <span style={{fontSize:"11px",color:T.sub,fontFamily:"sans-serif"}}>· {Number(spot.reviews).toLocaleString()} reviews</span>
          )}
          {spot.price && spot.price !== "?" && (
            <span style={{fontSize:"11px",color:nbAccent,fontFamily:"sans-serif",marginLeft:"auto",opacity:0.8}}>{spot.price}</span>
          )}
        </div>

        {spot.reservable && (
          <div style={{padding:"0 20px 14px"}}>
            <span style={{fontSize:"10px",color:T.sub,fontFamily:"sans-serif",opacity:0.7}}>✓ Takes Reservations</span>
          </div>
        )}
        {desc && (
          <div style={{padding:"0 20px 16px"}}>
            <p style={{margin:0,fontSize:"13px",color:T.sub,fontFamily:"sans-serif",lineHeight:1.6,fontStyle:"italic",opacity:0.85}}>{desc}</p>
          </div>
        )}
        {spot.deal && (
          <div style={{margin:"0 20px 16px",background:`${nbAccent}14`,border:`1px solid ${nbAccent}33`,borderRadius:"8px",padding:"10px 14px"}}>
            <div style={{fontSize:"12px",color:nbAccent,fontFamily:"sans-serif",fontWeight:"600"}}>{spot.deal}</div>
            {spot.hours && <p style={{fontSize:"11px",color:T.sub,fontFamily:"sans-serif",marginTop:"2px",margin:0}}>{spot.hours}</p>}
          </div>
        )}

        <div style={{padding:"4px 20px 22px",display:"flex",gap:"8px",flexWrap:"wrap"}}>
          {spot.booking && spot.booking !== "null" && (
            <a href={spot.booking} target="_blank" rel="noopener noreferrer"
              style={{flex:1,minWidth:"90px",padding:"12px 16px",background:nbAccent,borderRadius:"8px",fontSize:"10px",fontFamily:"sans-serif",letterSpacing:"2px",textTransform:"uppercase",color:"#000",textDecoration:"none",fontWeight:"800",textAlign:"center",display:"block"}}>
              Reserve
            </a>
          )}
          {dateType === "first" && spot.reservable && (
            <a href={resyUrl(spot.place)} target="_blank" rel="noopener noreferrer"
              style={{flex:1,minWidth:"90px",padding:"12px 16px",background:"transparent",border:`1px solid ${nbAccent}66`,borderRadius:"8px",fontSize:"10px",fontFamily:"sans-serif",letterSpacing:"2px",textTransform:"uppercase",color:nbAccent,textDecoration:"none",textAlign:"center",display:"block"}}>
              Resy
            </a>
          )}
          <a href={mapsUrl(spot)} target="_blank" rel="noopener noreferrer"
            style={{flex:1,minWidth:"90px",padding:"12px 16px",background:"transparent",border:"1px solid rgba(255,255,255,0.12)",borderRadius:"8px",fontSize:"10px",fontFamily:"sans-serif",letterSpacing:"2px",textTransform:"uppercase",color:T.sub,textDecoration:"none",textAlign:"center",display:"block"}}>
            Maps
          </a>
        </div>

        <div style={{height:"1px",background:`linear-gradient(90deg,transparent,${nbAccent}33,transparent)`}}/>
      </div>

      {remaining > 0 && (
        <button onClick={cycleNext}
          style={{width:"100%",background:"transparent",border:"1px solid rgba(255,255,255,0.1)",color:T.sub,padding:"14px",cursor:"pointer",fontFamily:"sans-serif",fontSize:"10px",letterSpacing:"2px",textTransform:"uppercase",borderRadius:"8px"}}>
          Show Another Pick ({remaining} more)
        </button>
      )}
      {remaining === 0 && (
        <button onClick={()=>setIdx(0)}
          style={{width:"100%",background:"transparent",border:"1px solid rgba(255,255,255,0.1)",color:T.sub,padding:"14px",cursor:"pointer",fontFamily:"sans-serif",fontSize:"10px",letterSpacing:"2px",textTransform:"uppercase",borderRadius:"8px"}}>
          See All Picks Again
        </button>
      )}

      <p style={{textAlign:"center",fontSize:"10px",color:T.sub,fontFamily:"sans-serif",opacity:0.5,margin:"0"}}>
        🔍 Always verify on Google Maps — NYC spots close unexpectedly.
      </p>

      <div style={{display:"flex",gap:"10px",marginTop:"2px"}}>
        <button onClick={onReset}
          style={{flex:1,background:"transparent",border:"1px solid rgba(255,255,255,0.1)",color:T.sub,padding:"13px",cursor:"pointer",fontFamily:"sans-serif",fontSize:"10px",letterSpacing:"2px",textTransform:"uppercase",borderRadius:"8px"}}>
          ↺ Start Over
        </button>
        <button
          style={{flex:2,background:`linear-gradient(135deg,${T.accent},${T.accent2})`,border:"none",color:T.bg,padding:"13px",cursor:"pointer",fontFamily:"sans-serif",fontSize:"10px",letterSpacing:"2px",textTransform:"uppercase",fontWeight:"800",borderRadius:"8px"}}
          onClick={()=>{
            const url = "https://partyof2nyc.com";
            const text = `${spot.place} — found on Party of Two 🍽️`;
            if (navigator.share) {
              navigator.share({title:"Party of Two", text, url}).catch(()=>{});
            } else {
              try { navigator.clipboard.writeText(url); alert("Link copied!"); }
              catch(e) { alert("Share: " + url); }
            }
          }}>
          📲 Share
        </button>
      </div>

    </div>
  );
}


export default function App() {
  const [screen, setScreen] = useState("intro");
  const [answers, setAnswers] = useState({});
  const [questionHistory, setQuestionHistory] = useState([]);
  const [currentQ, setCurrentQ] = useState(null);
  const [results, setResults] = useState(null);
  const [hoverNb, setHoverNb] = useState(null);

  const progress = Math.min((Object.keys(answers).length / 7) * 100, 95);

  const advance = (key, val) => {
    const next = { ...answers, [key]: val };
    setQuestionHistory(h => [...h, key]);
    setAnswers(next);
    const q = getQuestion(next);
    if (q) { setCurrentQ(q); setScreen("quiz"); }
    else { setScreen("loading"); setTimeout(() => { setResults(getSpots(next)); setScreen("result"); }, 1000); }
  };

  const goBack = () => {
    if (questionHistory.length === 0) { reset(); return; }
    const lastKey = questionHistory[questionHistory.length - 1];
    const newAnswers = { ...answers };
    delete newAnswers[lastKey];
    const newHistory = questionHistory.slice(0, -1);
    setQuestionHistory(newHistory);
    setAnswers(newAnswers);
    const q = getQuestion(newAnswers);
    if (q) { setCurrentQ(q); setScreen("quiz"); }
    else { setScreen("intro"); }
  };

  const reset = () => {
    setScreen("intro");
    setAnswers({});
    setQuestionHistory([]);
    setCurrentQ(null);
    setResults(null);
  };

  const resultTitle = () => {
    if (answers.budget === "free") return answers.dateType === "first" ? "Free First Date Ideas" : "Free Date Ideas";
    const t = answers.timeOfDay === "day" ? "Daytime" : answers.timeOfDay === "late" ? "Late Night" : "Tonight's";
    const map = { food:"Table", drinks:"Bar", fooddrinks:"Food & Drinks", activity:"Adventure", happyhour:"Happy Hours", brunch:"Brunch", coffee:"Coffee & Matcha" };
    return map[answers.focus] ? `${t} ${map[answers.focus]}` : "Your Picks";
  };

  const nbLabel = NEIGHBORHOODS.find(n => n.id === answers.neighborhood)?.label || "";

  return (
    <div style={{minHeight:"100vh",background:T.bg,color:T.text,display:"flex",alignItems:"center",justifyContent:"center",padding:"24px",fontFamily:"Georgia,serif",position:"relative",overflow:"hidden"}}>
      <div style={{position:"fixed",inset:0,pointerEvents:"none"}}>
        <div style={{position:"absolute",top:"8%",left:"20%",width:"600px",height:"600px",borderRadius:"50%",background:`radial-gradient(circle,${T.accent}07 0%,transparent 65%)`}}/>
        <div style={{position:"absolute",bottom:"10%",right:"10%",width:"400px",height:"400px",borderRadius:"50%",background:`radial-gradient(circle,${T.accent2}06 0%,transparent 65%)`}}/>
      </div>

      <div style={{position:"relative",zIndex:1,width:"100%",maxWidth:"520px"}}>

        {/* INTRO */}
        {screen === "intro" && (
          <div style={{textAlign:"center",animation:"fadeUp 0.7s ease"}}>
            <Skyline/>
            <div style={{marginTop:"20px",fontSize:"10px",letterSpacing:"6px",textTransform:"uppercase",color:T.accent,fontFamily:"sans-serif",marginBottom:"14px",opacity:0.7}}>New York City</div>
            <h1 style={{fontSize:"clamp(40px,9vw,62px)",fontWeight:"normal",lineHeight:1.0,margin:"0 0 6px",letterSpacing:"-2px"}}>
              Party of<br/>
              <span style={{background:`linear-gradient(135deg,${T.accent},${T.accent2})`,WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent"}}>Two</span>
            </h1>
            <div style={{width:"36px",height:"1px",background:`linear-gradient(90deg,${T.accent},${T.accent2})`,margin:"16px auto"}}/>
            <p style={{color:T.sub,fontSize:"13px",lineHeight:1.7,fontFamily:"sans-serif",marginBottom:"16px",opacity:0.85}}>The right place.<br/>Tonight.</p>
            <a href="https://instagram.com/partyof2nyc" target="_blank" rel="noopener noreferrer"
              style={{display:"inline-block",fontSize:"11px",color:T.accent,fontFamily:"sans-serif",letterSpacing:"1px",textDecoration:"none",marginBottom:"24px",opacity:0.7}}>
              @partyof2nyc
            </a>
            <div style={{display:"flex",flexDirection:"column",gap:"10px",alignItems:"center"}}>
              <button onClick={()=>{setScreen("quiz");setCurrentQ(getQuestion({}));}}
                style={{background:`linear-gradient(135deg,${T.accent},${T.accent2})`,border:"none",color:T.bg,padding:"14px 48px",cursor:"pointer",fontFamily:"sans-serif",fontSize:"11px",letterSpacing:"3px",textTransform:"uppercase",fontWeight:"800",borderRadius:"4px",transition:"transform 0.2s",width:"auto",alignSelf:"center"}}
                onMouseEnter={e=>e.currentTarget.style.transform="scale(1.04)"}
                onMouseLeave={e=>e.currentTarget.style.transform="scale(1)"}>
                Plan Our Night
              </button>
              <button onClick={()=>{advance("focus","ourpick");}}
                style={{background:"transparent",border:`1px solid ${T.border}`,color:T.sub,padding:"12px 32px",cursor:"pointer",fontFamily:"sans-serif",fontSize:"10px",letterSpacing:"3px",textTransform:"uppercase",borderRadius:"4px",transition:"all 0.2s"}}
                onMouseEnter={e=>{e.currentTarget.style.borderColor=T.accent;e.currentTarget.style.color=T.accent;}}
                onMouseLeave={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.color=T.sub;}}>
                ⭐ Tonight's Pick
              </button>
            </div>
          </div>
        )}
        {/* QUIZ */}
        {screen === "quiz" && currentQ && (
          <div style={{animation:"fadeUp 0.35s ease"}}>
            {currentQ.special !== "neighborhood" && (
              <div style={{marginBottom:"28px"}}>
                <div style={{height:"2px",background:"#111118",borderRadius:"1px",overflow:"hidden"}}>
                  <div style={{height:"100%",width:`${progress}%`,background:`linear-gradient(90deg,${T.accent},${T.accent2})`,transition:"width 0.4s ease"}}/>
                </div>
              </div>
            )}
            {currentQ.special === "neighborhood" ? (
              <div>
                <div style={{textAlign:"center",marginBottom:"24px"}}>
                  <div style={{fontSize:"10px",letterSpacing:"4px",textTransform:"uppercase",color:T.accent,fontFamily:"sans-serif",marginBottom:"6px"}}>Where are you going?</div>
                  <h2 style={{fontSize:"clamp(20px,5vw,26px)",fontWeight:"normal"}}>Pick your neighborhood</h2>
                </div>
                <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:"10px",marginBottom:"10px"}}>
                  {NEIGHBORHOODS.slice(0,8).map(nb => {
                    const SilSvg = NB_SILHOUETTES[nb.id];
                    const acc = {williamsburg:"#c9a96e",east_village:"#9b6b9b",west_village:"#6b9b8b",midtown:"#ff8c42",lic:"#c9a96e",bushwick:"#e85d75",fidi:"#6b8bbd",upper_east:"#9b6b9b",upper_west:"#6b9b8b"}[nb.id] || T.accent;
                    return (
                      <button key={nb.id} onClick={()=>advance("neighborhood",nb.id)}
                        style={{background:hoverNb===nb.id?`linear-gradient(135deg,${acc}22,${acc}08)`:T.card,border:hoverNb===nb.id?`1px solid ${acc}`:`1px solid ${T.border}`,color:T.text,padding:"0",cursor:"pointer",borderRadius:"6px",transition:"all 0.2s",display:"flex",flexDirection:"column",alignItems:"stretch",overflow:"hidden"}}
                        onMouseEnter={()=>setHoverNb(nb.id)}
                        onMouseLeave={()=>setHoverNb(null)}>
                        <div style={{padding:"10px 10px 0",background:`${acc}10`}}>
                          {SilSvg && <SilSvg/>}
                        </div>
                        <div style={{padding:"8px 12px 12px",textAlign:"center"}}>
                          <div style={{fontSize:"12px",fontFamily:"sans-serif",fontWeight:"700",marginBottom:"2px"}}>{nb.label}</div>
                          <div style={{fontSize:"10px",color:T.sub,fontFamily:"sans-serif"}}>{nb.sub}</div>
                        </div>
                      </button>
                    );
                  })}
                </div>
                <div style={{display:"flex",justifyContent:"center"}}>
                  {(() => {
                    const nb = NEIGHBORHOODS[8];
                    const SilSvg = NB_SILHOUETTES[nb.id];
                    const acc = {williamsburg:"#c9a96e",east_village:"#9b6b9b",west_village:"#6b9b8b",midtown:"#ff8c42",lic:"#c9a96e",bushwick:"#e85d75",fidi:"#6b8bbd",upper_east:"#9b6b9b",upper_west:"#6b9b8b"}[nb.id] || "#c9a96e";
                    return (
                      <button onClick={()=>advance("neighborhood",nb.id)}
                        style={{background:hoverNb===nb.id?`linear-gradient(135deg,${acc}22,${acc}08)`:T.card,border:hoverNb===nb.id?`1px solid ${acc}`:`1px solid ${T.border}`,color:T.text,padding:"0",cursor:"pointer",borderRadius:"6px",transition:"all 0.2s",display:"flex",flexDirection:"column",alignItems:"stretch",overflow:"hidden",width:"48%"}}
                        onMouseEnter={()=>setHoverNb(nb.id)}
                        onMouseLeave={()=>setHoverNb(null)}>
                        <div style={{padding:"8px 10px 0",background:`${acc}10`}}>
                          {SilSvg && <SilSvg/>}
                        </div>
                        <div style={{padding:"6px 12px 10px",textAlign:"center"}}>
                          <div style={{fontSize:"11px",fontFamily:"sans-serif",fontWeight:"700",marginBottom:"2px"}}>{nb.label}</div>
                          <div style={{fontSize:"10px",color:T.sub,fontFamily:"sans-serif"}}>{nb.sub}</div>
                        </div>
                      </button>
                    );
                  })()}
                </div>
              </div>
            ) : (
              <div>
                <div style={{textAlign:"center",marginBottom:"28px"}}>
                  <div style={{fontSize:"28px",marginBottom:"10px"}}>{currentQ.emoji}</div>
                  <h2 style={{fontSize:"clamp(18px,5vw,22px)",fontWeight:"normal",marginBottom:"6px"}}>{currentQ.q}</h2>
                </div>
                <div style={{display:"grid",gridTemplateColumns:currentQ.id==="foodType"?"1fr 1fr":(currentQ.opts||[]).length<=3?"repeat("+(currentQ.opts||[]).length+",1fr)":"1fr 1fr",gap:"8px"}}>
                  {currentQ.id === "foodType" ? (() => {
                    const opts = currentQ.opts;
                    const elems = [];
                    opts.forEach((o, oi) => {
                      const prevGroup = oi > 0 ? opts[oi-1].g : null;
                      if (prevGroup && prevGroup !== o.g) {
                        elems.push(<div key={"br"+oi} style={{gridColumn:"1/-1",height:"6px",borderTop:"1px solid rgba(255,255,255,0.08)"}}/>);
                      }
                      elems.push(
                        <button key={o.v} onClick={()=>advance(currentQ.id, o.v)}
                          style={{background:T.card,border:"1px solid "+T.border,color:T.text,padding:"4px 2px",cursor:"pointer",borderRadius:"4px",transition:"all 0.2s",display:"flex",flexDirection:"column",alignItems:"center",gap:"1px",fontFamily:"sans-serif"}}
                          onMouseEnter={e=>{e.currentTarget.style.borderColor=T.accent;e.currentTarget.style.background=T.accent+"12";}}
                          onMouseLeave={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.background=T.card;}}>
                          <span style={{fontSize:"12px"}}>{o.l.split(" ")[0]}</span>
                          <span style={{fontSize:"8px",fontWeight:"600",textAlign:"center",lineHeight:1.1,whiteSpace:"nowrap"}}>{o.l.split(" ").slice(1).join(" ")}</span>
                        </button>
                      );
                    });
                    return elems;
                  })() : currentQ.opts.map(o => (
                    <button key={o.v} onClick={()=>advance(currentQ.id, o.v)}
                      style={{background:T.card,border:`1px solid ${T.border}`,color:T.text,padding:"8px 6px",cursor:"pointer",borderRadius:"5px",transition:"all 0.2s",display:"flex",flexDirection:"column",alignItems:"center",gap:"3px",fontFamily:"sans-serif"}}
                      onMouseEnter={e=>{e.currentTarget.style.borderColor=T.accent;e.currentTarget.style.background=`${T.accent}12`;}}
                      onMouseLeave={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.background=T.card;}}>
                      {o.i && <span style={{fontSize:"16px"}}>{o.i}</span>}
                      <span style={{fontSize:"10px",fontWeight:"600",textAlign:"center",lineHeight:1.2}}>{o.l}</span>
                    </button>
                  ))}
                </div>
              </div>
            )}

            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginTop:"24px"}}>
              {questionHistory.length > 0 && (
                <button onClick={goBack}
                  style={{background:"transparent",border:"none",color:T.accent,fontSize:"11px",fontFamily:"sans-serif",cursor:"pointer",letterSpacing:"1px",padding:"0",opacity:0.85}}
                  onMouseEnter={e=>e.currentTarget.style.opacity="1"}
                  onMouseLeave={e=>e.currentTarget.style.opacity="0.85"}>
                  ← back
                </button>
              )}
              <div style={{flex:1}}/>
              <button onClick={reset}
                style={{background:"transparent",border:"none",color:T.accent,fontSize:"10px",fontFamily:"sans-serif",cursor:"pointer",letterSpacing:"1px",padding:"0",opacity:0.85}}
                onMouseEnter={e=>e.currentTarget.style.opacity="1"}
                onMouseLeave={e=>e.currentTarget.style.opacity="0.85"}>
                start over
              </button>
            </div>
          </div>
        )}
        {/* LOADING */}
        {screen === "loading" && (
          <div style={{textAlign:"center",animation:"fadeUp 0.4s ease"}}>
            <div style={{fontSize:"40px",marginBottom:"16px",animation:"pulse 1s ease infinite"}}>🗽</div>
            <div style={{fontSize:"11px",letterSpacing:"4px",textTransform:"uppercase",color:T.accent,fontFamily:"sans-serif"}}>Finding your spot...</div>
            <div style={{marginTop:"16px",display:"flex",gap:"7px",justifyContent:"center"}}>
              {[0,1,2].map(i => <div key={i} style={{width:"5px",height:"5px",borderRadius:"50%",background:T.accent,animation:`bounce 1s ease ${i*0.15}s infinite`}}/>)}
            </div>
          </div>
        )}
        {/* RESULT */}
        {screen === "result" && results && (
          <div style={{animation:"fadeUp 0.5s ease"}}>
            <div style={{textAlign:"center",marginBottom:"20px"}}>
              <div style={{fontSize:"10px",letterSpacing:"4px",textTransform:"uppercase",color:T.accent,fontFamily:"sans-serif",marginBottom:"5px"}}>{nbLabel}</div>
              <h2 style={{fontSize:"clamp(20px,5vw,26px)",fontWeight:"normal",marginBottom:"4px"}}>{resultTitle()}</h2>
              <div style={{width:"32px",height:"1px",background:T.accent,margin:"8px auto",opacity:0.4}}/>
            </div>
            <ResultCards spots={results} mode={answers.focus} dateType={answers.dateType} onReset={reset} neighborhood={answers.neighborhood} answers={answers}/>
          </div>
        )}

      </div>

      <style>{`
        @keyframes fadeUp{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
        @keyframes pulse{0%,100%{transform:scale(1);opacity:.7}50%{transform:scale(1.1);opacity:1}}
        @keyframes bounce{0%,100%{transform:translateY(0);opacity:.4}50%{transform:translateY(-8px);opacity:1}}
      `}</style>
    </div>
  );
}
